set client_min_messages = warning;

alter table public.staff_onboarding_templates
  add column if not exists fields jsonb default '[]'::jsonb,
  add column if not exists employment_type text default 'contractor',
  add column if not exists employer_entity_type text,
  add column if not exists employer_entity_id uuid;

insert into public.staff_onboarding_templates (
  name, description, department, position, employment_type, fields, estimated_days,
  required_documents, tags, is_default, employer_entity_type, employer_entity_id, created_at, updated_at
)
select
  'New Staff',
  'Standard onboarding for newly hired event staff and contractors.',
  'General', 'New Staff', 'contractor',
  '[{"id":"legal_name","name":"legal_name","label":"Legal full name","type":"text","section":"Identity","order":10,"required":true,"blocking":true},{"id":"preferred_name","name":"preferred_name","label":"Preferred name","type":"text","section":"Identity","order":20,"required":false},{"id":"date_of_birth","name":"date_of_birth","label":"Date of birth","type":"date","section":"Identity","order":30,"required":true,"blocking":true,"validation":{"minimumAge":16}},{"id":"phone","name":"phone","label":"Mobile phone","type":"phone","section":"Contact","order":100,"required":true,"blocking":true},{"id":"address","name":"address","label":"Home address","type":"address","section":"Contact","order":110,"required":true,"blocking":true},{"id":"emergency_contact","name":"emergency_contact","label":"Emergency contact","type":"emergency_contact","section":"Emergency Contact","order":120,"required":true,"blocking":true},{"id":"work_authorization","name":"work_authorization","label":"I am legally authorized to work for this engagement","type":"checkbox","section":"Work Eligibility","order":200,"required":true,"blocking":true},{"id":"government_id","name":"government_id","label":"Government ID","type":"id_document","section":"Documents","order":300,"required":true,"blocking":true,"requiresAdminReview":true,"credentialType":"government_id"},{"id":"w9_or_tax_form","name":"w9_or_tax_form","label":"W-9 / tax form","type":"tax_info","section":"Tax / Payment","order":400,"required":true,"blocking":true,"requiresAdminReview":true,"credentialType":"tax_form"},{"id":"worker_agreement","name":"worker_agreement","label":"Worker agreement","type":"waiver","section":"Agreements","order":500,"required":true,"blocking":true,"metadata":{"agreementType":"worker","requiresAcknowledgement":true,"agreementBody":"By accepting, you agree to perform your assigned duties professionally, follow all event and venue policies, and understand that this engagement is at-will unless a separate written contract states otherwise. You confirm that the information you provide is accurate and complete."}},{"id":"event_safety_disclaimer","name":"event_safety_disclaimer","label":"Event safety disclaimer","type":"waiver","section":"Agreements","order":510,"required":true,"blocking":true,"metadata":{"agreementType":"safety","requiresAcknowledgement":true,"agreementBody":"You acknowledge that live events involve inherent risks. You agree to follow all safety directions from event staff, wear any required protective equipment, report hazards immediately, and refrain from unsafe behavior. You release the organizer from liability for injuries arising from your failure to follow safety instructions."}}]'::jsonb,
  2, array['Government ID','W-9 or tax form','Worker agreement'], array['default','new-staff','staff'], true, null, null, now(), now()
where not exists (select 1 from public.staff_onboarding_templates where name='New Staff' and employer_entity_type is null and employer_entity_id is null);

insert into public.staff_onboarding_templates (
  name, description, department, position, employment_type, fields, estimated_days,
  required_documents, tags, is_default, employer_entity_type, employer_entity_id, created_at, updated_at
)
select
  'Volunteers', 'Lightweight onboarding for event volunteers donating their time.', 'Volunteer', 'Volunteer', 'volunteer',
  '[{"id":"legal_name","name":"legal_name","label":"Legal full name","type":"text","section":"Identity","order":10,"required":true,"blocking":true},{"id":"preferred_name","name":"preferred_name","label":"Preferred name","type":"text","section":"Identity","order":20,"required":false},{"id":"date_of_birth","name":"date_of_birth","label":"Date of birth","type":"date","section":"Identity","order":30,"required":true,"blocking":true,"validation":{"minimumAge":16}},{"id":"phone","name":"phone","label":"Mobile phone","type":"phone","section":"Contact","order":100,"required":true,"blocking":true},{"id":"emergency_contact","name":"emergency_contact","label":"Emergency contact","type":"emergency_contact","section":"Emergency Contact","order":120,"required":true,"blocking":true},{"id":"volunteer_waiver","name":"volunteer_waiver","label":"Volunteer waiver","type":"waiver","section":"Agreements","order":500,"required":true,"blocking":true,"metadata":{"agreementType":"volunteer","requiresAcknowledgement":true,"agreementBody":"As a volunteer you are donating your time and are not an employee or contractor. You agree to follow all event conduct and safety policies, understand that you will not receive wages, and accept the general risks of participating in a live event. You release the organizer from liability for injuries arising from your failure to follow safety instructions."}},{"id":"photo_release","name":"photo_release","label":"I consent to the use of my likeness in event photos and video","type":"checkbox","section":"Agreements","order":510,"required":false,"blocking":false}]'::jsonb,
  1, array['Volunteer waiver'], array['volunteer','crew'], false, null, null, now(), now()
where not exists (select 1 from public.staff_onboarding_templates where name='Volunteers' and employer_entity_type is null and employer_entity_id is null);

insert into public.staff_onboarding_templates (
  name, description, department, position, employment_type, fields, estimated_days,
  required_documents, tags, is_default, employer_entity_type, employer_entity_id, created_at, updated_at
