select
  'Media', 'Onboarding for press, photographers, and content creators covering the event.', 'Media', 'Media', 'contractor',
  '[{"id":"legal_name","name":"legal_name","label":"Legal full name","type":"text","section":"Identity","order":10,"required":true,"blocking":true},{"id":"preferred_name","name":"preferred_name","label":"Preferred name","type":"text","section":"Identity","order":20,"required":false},{"id":"phone","name":"phone","label":"Mobile phone","type":"phone","section":"Contact","order":100,"required":true,"blocking":true},{"id":"outlet","name":"outlet","label":"Outlet / publication","type":"text","section":"Contact","order":110,"required":false},{"id":"press_credential","name":"press_credential","label":"Press credential or portfolio","type":"file","section":"Certifications","order":250,"required":false,"requiresAdminReview":true,"credentialType":"press_credential","validation":{"fileTypes":["image/jpeg","image/png","application/pdf"],"maxFileSizeMb":10}},{"id":"government_id","name":"government_id","label":"Government ID","type":"id_document","section":"Documents","order":300,"required":false,"requiresAdminReview":true,"credentialType":"government_id"},{"id":"media_release","name":"media_release","label":"Media release","type":"waiver","section":"Agreements","order":500,"required":true,"blocking":true,"metadata":{"agreementType":"media_release","requiresAcknowledgement":true,"agreementBody":"You grant the organizer and its partners the irrevocable right to record, use, and distribute your likeness and voice, and to use footage you capture in connection with the event across all media and platforms, without additional compensation. You confirm you have the right to grant this release."}},{"id":"nda","name":"nda","label":"Confidentiality agreement (NDA)","type":"waiver","section":"Agreements","order":510,"required":true,"blocking":true,"metadata":{"agreementType":"nda","requiresAcknowledgement":true,"agreementBody":"You agree to keep confidential all non-public information you learn about artists, productions, guests, and operations, and not to share, publish, or leak such information without prior written authorization from the organizer."}}]'::jsonb,
  1, array['Media release','NDA'], array['media','press','content'], false, null, null, now(), now()
where not exists (select 1 from public.staff_onboarding_templates where name='Media' and employer_entity_type is null and employer_entity_id is null);

insert into public.staff_onboarding_templates (
  name, description, department, position, employment_type, fields, estimated_days,
