select
  'Security', 'Compliance onboarding for licensed security staff.', 'Security', 'Security', 'contractor',
  '[{"id":"legal_name","name":"legal_name","label":"Legal full name","type":"text","section":"Identity","order":10,"required":true,"blocking":true},{"id":"preferred_name","name":"preferred_name","label":"Preferred name","type":"text","section":"Identity","order":20,"required":false},{"id":"date_of_birth","name":"date_of_birth","label":"Date of birth","type":"date","section":"Identity","order":30,"required":true,"blocking":true,"validation":{"minimumAge":18}},{"id":"phone","name":"phone","label":"Mobile phone","type":"phone","section":"Contact","order":100,"required":true,"blocking":true},{"id":"address","name":"address","label":"Home address","type":"address","section":"Contact","order":110,"required":true,"blocking":true},{"id":"emergency_contact","name":"emergency_contact","label":"Emergency contact","type":"emergency_contact","section":"Emergency Contact","order":120,"required":true,"blocking":true},{"id":"guard_card","name":"guard_card","label":"Guard card / security license","type":"file","section":"Certifications","order":250,"required":true,"blocking":true,"requiresAdminReview":true,"credentialType":"guard_card","validation":{"fileTypes":["image/jpeg","image/png","application/pdf"],"maxFileSizeMb":10}},{"id":"government_id","name":"government_id","label":"Government ID","type":"id_document","section":"Documents","order":300,"required":true,"blocking":true,"requiresAdminReview":true,"credentialType":"government_id"},{"id":"w9_or_tax_form","name":"w9_or_tax_form","label":"W-9 / tax form","type":"tax_info","section":"Tax / Payment","order":400,"required":true,"blocking":true,"requiresAdminReview":true,"credentialType":"tax_form"},{"id":"security_conduct","name":"security_conduct","label":"Security conduct & use-of-force disclaimer","type":"waiver","section":"Agreements","order":500,"required":true,"blocking":true,"metadata":{"agreementType":"security_conduct","requiresAcknowledgement":true,"agreementBody":"You agree to act lawfully and professionally, use only reasonable and necessary force consistent with your training and applicable law, de-escalate whenever possible, follow the incident reporting chain, and never discriminate against or harass any person. Violation of this policy may result in immediate removal from the engagement."}},{"id":"event_safety_waiver","name":"event_safety_waiver","label":"Event safety waiver","type":"waiver","section":"Agreements","order":510,"required":true,"blocking":true,"metadata":{"agreementType":"safety","requiresAcknowledgement":true,"agreementBody":"You acknowledge that live events involve inherent risks. You agree to follow all safety directions, wear any required protective equipment, report hazards immediately, and refrain from unsafe behavior. You release the organizer from liability for injuries arising from your failure to follow safety instructions."}}]'::jsonb,
  3, array['Government ID','Guard card','W-9 or tax form','Security agreements'], array['security','licensed','compliance'], false, null, null, now(), now()
where not exists (select 1 from public.staff_onboarding_templates where name='Security' and employer_entity_type is null and employer_entity_id is null);

update public.staff_onboarding_templates
set is_default = false, updated_at = now()
where employer_entity_type is null and employer_entity_id is null and is_default = true and name <> 'New Staff';;
